using StarOutpost;
using System.Numerics;
using System.Text.Json;
using System.Diagnostics;
var results=new List<string>();
void Check(bool condition,string message){if(!condition)throw new Exception(message);}
void Test(string name,Action run){run();results.Add(name+" PASS");Console.WriteLine(results[^1]);}
Simulation Fresh(){var g=new Simulation(seed:19);g.Start();return g;}
Test("T1 automatic fire and bounded cadence",()=>{var g=Fresh();var e=g.SpawnEnemy(0,new(0,2));e.Hp=e.MaxHp=100;for(int i=0;i<60;i++)g.Tick(1f/60,Vector2.Zero,Vector2.UnitY);Check(g.ShotCount>0&&g.ShotCount<=5,"fire cadence");Check(e.Hp<100,"no projectile damage");});
Test("T2 second choice adds moon blade and preserves XP",()=>{var g=Fresh();g.Exp=Rules.ExpNext(1)+7;g.Tick(1f/60,Vector2.Zero);Check(g.State==Flow.Upgrade&&g.Exp==7,"upgrade subtraction");g.Choices=[new("passive0","","",4,0),new("new1","","",0,1),new("passive1","","",4,1)];Check(g.Choose(1)&&g.Weapons[1]==1&&g.State==Flow.Run&&g.Exp==7,"second choice");});
Test("T3 full upgrades excluded and unique choices",()=>{var g=Fresh();g.Weapons[0]=5;g.Evolution[0]=1;g.Passives[0]=5;for(int n=0;n<200;n++){var offers=g.DrawChoices();Check(offers.Length==3&&offers.Select(x=>x.Id).Distinct().Count()==3,"duplicate choice");Check(offers.All(x=>x.Id!="weapon0"&&x.Id!="passive0"&&!x.Id.StartsWith("evo0")),"full item remained");}Check(g.CandidateRarities.Sum()==600&&g.ChosenRarities.Sum()==0,"candidate/selection counters conflated");});
Test("T4 readable charge, miss and recovery",()=>{var g=Fresh();Array.Clear(g.Weapons);var e=g.SpawnEnemy(1,new(0,3));e.Phase=1;e.Timer=1;e.Direction=new(0,-1);g.Player=new(2,0);for(int i=0;i<61;i++)g.Tick(1f/60,Vector2.Zero);Check(e.Phase==2,"charge did not wait 1 second");for(int i=0;i<28;i++)g.Tick(1f/60,Vector2.Zero);Check(e.Phase==3&&e.Timer>.4f,"missing .6s recovery");Check(g.Hp==g.MaxHp,"charge failed to miss");});
Test("T5 death wallet credited exactly once",()=>{var g=Fresh();g.RunGold=1234;g.RunStars=3;g.Hp=0;g.Tick(1f/60,Vector2.Zero);Check(g.State==Flow.Result&&g.Profile.GoldTenths==1234&&g.Profile.Stars==3,"death reward");g.Hurt(10,0);g.Finish(false);Check(g.Profile.GoldTenths==1234,"double credit");});
Test("T6 empty detonation explicit refusal",()=>{var g=Fresh();Check(!g.Detonate()&&g.Notice=="无碎尸","missing refusal");});
Test("T7 809 minus 700 and persisted meta",()=>{var p=new Profile{GoldTenths=8090};p.Meta[0]=3;Check(p.BuyMeta(0)&&p.GoldTenths==1090&&p.Meta[0]==4,"shop account");var restored=JsonSerializer.Deserialize<Profile>(JsonSerializer.Serialize(p))!;var g=new Simulation(restored);g.Start();Check(g.DamageMultiplier==1.4f,"meta not applied");});
Test("T8 enemy cap and oldest-first replacement",()=>{var g=Fresh();Array.Clear(g.Weapons);for(int i=0;i<600;i++)g.SpawnEnemy(0,new(11,7));int oldest=g.Enemies.MinBy(e=>e.Born)!.Id;var replaced=g.SpawnEnemy(0,new(11,7));Check(!g.Enemies.Any(e=>e.Id==oldest)&&replaced.Active&&g.Enemies.Count(e=>e.Active)==600,"oldest replacement");for(int i=0;i<1800;i++){g.Invulnerable=1;g.Tick(1f/60,Vector2.Zero);}Check(g.Enemies.Count(e=>e.Active)<=600&&g.Bullets.Count(b=>b.Active)<=400&&g.Particles.Count(p=>p.Active)<=1200,"cap violated");});
Test("Pause freezes exact state",()=>{var g=Fresh();g.Advance(.01f,Vector2.One);g.State=Flow.Pause;float t=g.Elapsed;Vector2 p=g.Player;g.Advance(10,Vector2.One,true?Vector2.UnitX:null,true,true);Check(g.Elapsed==t&&g.Player==p,"pause update");g.State=Flow.Run;g.Advance(.01f,Vector2.Zero);Check(g.Elapsed>t,"fractional remainder lost");});
Test("Pierce cannot damage same identity twice",()=>{var g=Fresh();Array.Clear(g.Weapons);var e=g.SpawnEnemy(0,new(0,1));e.Hp=1000;var b=g.Bullets[0];b.Active=true;b.Position=e.Position;b.Velocity=Vector2.Zero;b.Damage=8;b.Pierce=4;b.Life=10;for(int i=0;i<6;i++)g.Tick(1f/60,Vector2.Zero);Check(Math.Abs(e.Hp-992)<.01f,"duplicate hit");});
Test("Death and pickup settled once",()=>{var g=Fresh();var e=g.SpawnEnemy(4,Vector2.Zero);e.Hp=0;g.SettleDeaths();g.SettleDeaths();Check(g.Kills==1&&g.Drops.Count(d=>d.Active)==1,"duplicate death");for(int i=0;i<10;i++){g.Tick(1f/60,Vector2.Zero);if(g.State==Flow.Upgrade)g.Choose(0);}Check(g.RunGold==100&&g.RunStars==3,"duplicate pickup");});
Test("Supply payment atomic and limited",()=>{var g=Fresh();g.RunGold=300;g.Profile.GoldTenths=400;g.SupplyAvailable=true;g.SupplyPosition=g.Player;g.Hp=50;Check(g.OpenSupply()&&g.BuySupply(0),"supply purchase");Check(g.RunGold==0&&g.Profile.GoldTenths==100&&g.Hp==90&&!g.SupplyAvailable,"supply payment");Check(!g.BuySupply(0),"repeat supply purchase");});
Test("All weapons damage, evolutions and pool exhaustion",()=>{for(int i=0;i<7;i++){var g=Fresh();Array.Clear(g.Weapons);g.Profile.Unlocked[i]=true;g.Weapons[i]=5;g.Evolution[i]=1;var e=g.SpawnEnemy(0,i==1?new(1.1f,0):new(0,1));e.Hp=10000;for(int n=0;n<120;n++)g.Tick(1f/60,Vector2.Zero,Vector2.UnitY);Check(e.Hp<10000,"weapon inactive "+i);}var full=Fresh();Array.Fill(full.Profile.Unlocked,true);Array.Fill(full.Weapons,5);Array.Fill(full.Evolution,1);Array.Fill(full.Passives,5);Check(full.DrawChoices().Length==3,"no endgame fallback");});
Test("Active energy rejection and boss interruption",()=>{var g=Fresh();Check(!g.ActiveSkill()&&g.Notice.Contains("能量"),"energy refusal");var b=g.SpawnEnemy(5,new(0,2));b.Phase=1;g.Energy=100;Check(g.ActiveSkill()&&g.Energy==0&&b.Phase==0&&g.Cooldown>0,"boss interrupt");});
Test("20 minute full simulation with all systems",()=>{var g=Fresh();Array.Fill(g.Profile.Unlocked,true);for(int i=0;i<7;i++)g.Weapons[i]=1;var sw=Stopwatch.StartNew();int frames=0;while(g.State!=Flow.Result&&frames<220000){g.Invulnerable=1;if(g.State==Flow.Upgrade)g.Choose(0);else g.Tick(1f/60,new(MathF.Cos(g.Elapsed*.3f),MathF.Sin(g.Elapsed*.3f)),null,g.Energy>=100,frames%180==0);frames++;}Check(g.Won&&g.Elapsed>=1200,"20 minute victory failed");Check(g.Kills>500&&g.Level>10,"long simulation did not exercise progression");Console.WriteLine($"Long run: {frames} steps, {sw.Elapsed.TotalSeconds:F2}s CPU, kills {g.Kills}, level {g.Level}, gold {g.RunGold/10f:F1}");});
Test("Wave schedule starts empty and spawns progressively",()=>{var g=new Simulation();Check(g.Enemies.All(e=>!e.Active),"menu already has enemies");g.Tick(10,Vector2.Zero);Check(g.Enemies.All(e=>!e.Active),"menu advances waves");g.Start();Check(g.Enemies.All(e=>!e.Active),"start prefilled enemies");Array.Clear(g.Weapons);g.Tick(1f/60,Vector2.Zero);Check(g.Enemies.Count(e=>e.Active)==1,"first step must spawn one enemy");for(int i=0;i<119;i++)g.Tick(1f/60,Vector2.Zero);Check(g.Enemies.Count(e=>e.Active) is >=4 and <=5,"opening spawn rate");g.State=Flow.Pause;int count=g.Enemies.Count(e=>e.Active);g.Tick(10,Vector2.Zero);Check(g.Enemies.Count(e=>e.Active)==count,"paused spawner");});
Test("Native actor scripts own updates and pending actors cannot hit",()=>{var g=Fresh();g.NativeActors=true;g.SpawnerStep=_=>{};Array.Clear(g.Weapons);var enemy=g.SpawnEnemy(0,Vector2.Zero);g.Tick(1f/60,Vector2.Zero);Check(g.Hp==100&&!g.IsTargetable(enemy),"unbound invisible enemy attacked");int calls=0;g.EnemySteps[enemy.Slot]=dt=>{calls++;EnemyLogic.Tick(g,enemy,dt);};g.Tick(1f/60,Vector2.Zero);Check(calls==1&&g.Hp<100&&g.IsTargetable(enemy),"enemy script did not own fixed behavior");});
Test("Up input projects upward and down projects downward",()=>{float pitch=MathF.Atan2(17,12);var inverse=Quaternion.Inverse(Quaternion.CreateFromAxisAngle(Vector3.UnitX,pitch));float ScreenY(Vector2 position){var v=Vector3.Transform(new Vector3(position.X,.4f,position.Y)-new Vector3(0,17,-12),inverse);return -v.Y/v.Z;}var g=Fresh();float initial=ScreenY(g.Player);PlayerLogic.Tick(g,.1f,Vector2.UnitY,null);Check(g.Player.Y>0&&ScreenY(g.Player)<initial,"W/up moves screen downward");g.Player=Vector2.Zero;PlayerLogic.Tick(g,.1f,-Vector2.UnitY,null);Check(g.Player.Y<0&&ScreenY(g.Player)>initial,"S/down moves screen upward");});
Test("Repeated hits and deaths preserve the fixed clock and movement",()=>{var g=Fresh();Array.Clear(g.Weapons);g.SpawnerStep=_=>{};g.Cooldown=2;for(int i=0;i<60;i++){var e=g.SpawnEnemy(0,new(10,7));g.Hit(e,1000,Vector2.UnitX);g.Tick(1f/60,Vector2.UnitX);}Check(g.Kills==60,"kills not exercised");Check(Math.Abs(g.Elapsed-1)<.00001f&&Math.Abs(g.Player.X-g.MoveSpeed)<.00001f,"combat feedback slowed time or input");Check(Math.Abs(g.Cooldown-1)<.00001f,"cooldown drifted from simulation clock");Check(g.Particles.Any(p=>p.Active)&&g.Corpses.Count==60,"visual feedback disappeared");});
Test("Explosive chain settles once without changing time",()=>{var g=Fresh();Array.Clear(g.Weapons);g.SpawnerStep=_=>{};var a=g.SpawnEnemy(2,new(10,7));var b=g.SpawnEnemy(2,new(10.1f,7));var c=g.SpawnEnemy(0,new(10.2f,7));a.Hp=1;b.Hp=c.Hp=10;g.Hit(a,2,Vector2.Zero);g.Tick(1f/60,Vector2.Zero);Check(g.Kills==3&&Math.Abs(g.Elapsed-1f/60)<1e-7f,"chain kill settlement or clock");g.SettleDeaths();Check(g.Kills==3&&g.Drops.Count(d=>d.Active)==3,"chain rewarded twice");});
Test("Unavailable native burst falls back without interrupting combat",()=>{var g=Fresh();Array.Clear(g.Weapons);g.SpawnerStep=_=>{};int attempts=0;g.BurstEffect=(_,_)=>{attempts++;return false;};for(int i=0;i<60;i++){var e=g.SpawnEnemy(0,new(10,7));g.Hit(e,1000,Vector2.Zero);g.Tick(1f/60,Vector2.UnitX);}Check(attempts==120&&g.Kills==60&&Math.Abs(g.Elapsed-1)<.00001f,"unavailable effect stopped combat");Check(g.Particles.Any(p=>p.Active),"missing fallback visuals");});
Test("Successful native burst avoids duplicate mesh particles",()=>{var g=Fresh();g.BurstEffect=(_,_)=>true;g.Burst(Vector2.Zero,8,2);Check(g.Particles.All(p=>!p.Active),"native burst duplicated mesh visuals");});
string path=Path.Combine(AppContext.BaseDirectory,"acceptance-results.txt");File.WriteAllLines(path,results);Console.WriteLine($"{results.Count} checks passed: {path}");
